# shellcheck shell=bash
# Sourced by install.sh: the Harvest Sprite crew rendered into six harnesses by scripts/gen-sprite-agents.mjs.
#
# Each harness gets its own format (hex colors and permission rules for OpenCode, a TOML agent for
# Codex, and so on), and the files carry a "# Generated by scripts/gen-sprite-agents.mjs" line: the
# generator writes and removes only files that carry it, and refuses a hand-written file with a sprite
# name. Claude Code is rendered with --hook-root, because a user-level agent runs in every project,
# where $CLAUDE_PROJECT_DIR is that project and has no git guard hook, so the hook path is pinned to
# this repository. Revert by hand: rm the files in the sprite dir that carry the marker line, or run
# ./install.sh --uninstall.

# Ids of the harnesses whose renderer failed during this run, space separated. install and update
# finish everything else first and then exit 1 (sprites_exit_if_failed).
SPRITES_FAILED=""

# The generator target for a harness id, or return 1 for a harness without sprite agents.
sprite_target() {
  case "$1" in
    claude | opencode | codex | cursor | copilot | antigravity) echo "$1" ;;
    *) return 1 ;;
  esac
}

sprite_out_dir() {
  case "$1" in
    claude) echo "$HOME/.claude/agents" ;;
    opencode) echo "$HOME/.config/opencode/agents" ;;
    codex) echo "$HOME/.codex/agents" ;;
    cursor) echo "$HOME/.cursor/agents" ;;
    copilot) echo "$HOME/.copilot/agents" ;;
    antigravity) echo "$HOME/.gemini/config/agents" ;;
    *) return 1 ;;
  esac
}

# What the dry-run line says about the format of the files.
sprite_note() {
  case "$1" in
    claude) echo "hook root $REPO_DIR" ;;
    opencode) echo "OpenCode format" ;;
    codex) echo "Codex format" ;;
    cursor) echo "Cursor format" ;;
    copilot) echo "Copilot format" ;;
    antigravity) echo "Antigravity format" ;;
    *) return 1 ;;
  esac
}

# True when the sprite dir, or the nearest directory that exists above it, lives in this checkout
# (~/.claude/agents symlinked to <repo>/.claude/agents): the generator would rewrite tracked files.
sprite_dir_in_repo() {
  local dir="$1"
  while [ ! -d "$dir" ] && [ "$dir" != "/" ]; do
    dir="$(dirname "$dir")"
  done
  dest_in_repo "$dir/x"
}

# Sets SPRITE_ARGS to the generator arguments of one harness (the caller adds --check or --clean).
set_sprite_args() {
  local id="$1"
  SPRITE_ARGS=(--target "$(sprite_target "$id")" --out "$(sprite_out_dir "$id")")
  if [ "$id" = claude ]; then
    SPRITE_ARGS+=(--hook-root "$REPO_DIR")
  fi
}

# Install and update. Tier minimal renders nothing (the generator needs bun); install_targets prints the
# one line that says so. A generator that fails is reported, remembered and does not stop the others.
render_sprites() {
  local id="$1"
  local dir

  if ! sprite_target "$id" >/dev/null || [ "$TIER" = minimal ]; then
    return 0
  fi
  dir="$(sprite_out_dir "$id")"
  if sprite_dir_in_repo "$dir"; then
    left_alone "$id sprites: $dir is inside this checkout; left alone"
    return 0
  fi
  if [ "$DRY_RUN" = true ]; then
    echo "[DRY-RUN] Would render the sprite agents into: $dir ($(sprite_note "$id"))"
    return 0
  fi
  set_sprite_args "$id"
  if ! bun "$REPO_DIR/scripts/gen-sprite-agents.mjs" "${SPRITE_ARGS[@]}"; then
    echo "[FAIL] sprite agents for $id could not be rendered (see above)" >&2
    SPRITES_FAILED="${SPRITES_FAILED:+$SPRITES_FAILED }$id"
  fi
}

# Last step of install and update: if any renderer failed, everything else is already done, so say so
# and exit 1 instead of announcing success.
sprites_exit_if_failed() {
  if [ -n "$SPRITES_FAILED" ]; then
    echo "==> Vivera finished, but the sprite agents failed for: $SPRITES_FAILED (see [FAIL] above)" >&2
    exit 1
  fi
  # Entries left alone (inside the checkout, behind a symlinked dir) are not a failure, but the closing
  # line must not claim a complete install: it counts them instead and ends the run here.
  finish_if_left_alone
}
